SET TIME ZONE 'UTC';

-- 1. Tahun fiskal berjalan
SELECT gen_random_uuid()::text, y::text, make_date(y, 1, 1)::timestamp, make_date(y, 12, 31)::timestamp, false, now()
FROM (SELECT EXTRACT(YEAR FROM now())::int AS y) t
ON CONFLICT (name) DO NOTHING;

-- 2. Bagan akun standar (PSAK). Akun yang sudah ada tidak diubah.
UPDATE accounts SET description = 'Uang muka operasional / perjalanan dinas yang dibayarkan ke karyawan dan wajib dipertanggungjawabkan.' WHERE account_number = '1.5.6' AND description IS NULL;

-- 3. Pemetaan akun sistem (hanya bila role belum dipetakan sama sekali)

-- 4. Jenis pengajuan pembayaran bawaan (hanya ke tabel kosong)

-- 5. Pengaturan perusahaan (diisi admin di Pengaturan ERP)
VALUES (gen_random_uuid()::text, 'default', '', '', '', '', '', 'IDR', 1, 'id') ON CONFLICT (slug) DO NOTHING;

-- 6. Gudang utama (default) agar alur stok multi-gudang langsung bisa dipakai
SELECT gen_random_uuid()::text, 'GDG-UTAMA', 'Gudang Utama', TRUE, TRUE, 0, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM warehouses);

